package com.fittrack.auth;
import jakarta.persistence.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="app_users") public class User { @Id UUID id; @Column(nullable=false,unique=true) String email; @Column(nullable=false) String passwordHash; @Column(nullable=false) boolean enabled=true; @ElementCollection @CollectionTable(name="user_roles",joinColumns=@JoinColumn(name="user_id")) @Column(name="role") java.util.Set<String> roles=new java.util.HashSet<>(java.util.Set.of("USER")); @PrePersist void create(){if(id==null)id=UUID.randomUUID();} public UUID getId(){return id;} public void setId(UUID v){id=v;} public String getEmail(){return email;} public void setEmail(String v){email=v.toLowerCase();} public String getPasswordHash(){return passwordHash;} public void setPasswordHash(String v){passwordHash=v;} public boolean isEnabled(){return enabled;} public void setEnabled(boolean v){enabled=v;} public java.util.Set<String> getRoles(){return roles;} }
